2. import { Executor, isPromise, MaybePromise } from '@graphql-tools/utils';
3. import { schemaFromExecutor } from '@graphql-tools/wrap';
4. 
5. type GraphQLSchema = any;
6. 
7. export interface ExecutorPluginContext {
8.   schema$?: MaybePromise<GraphQLSchema>;
9.   schema?: GraphQLSchema;
10.   schemaSetPromise$?: Promise<void>;
11.   skipIntrospection: boolean;
12. }
13. 
14. export type ExecutorPluginOpts = Parameters<typeof schemaFromExecutor>[2] & {
15.   polling?: number;
16. };
17. 
18. export interface ExecutorPluginExtras {
19.   invalidateUnifiedGraph: () => void;
20.   pluginCtx: ExecutorPluginContext;
21.   ensureSchema(ctx?: any): void;
22. }
23. 
24. export function useExecutor<TPluginContext extends Record<string, any>>(
25.   executor: Executor,
26.   opts?: ExecutorPluginOpts,
27. ): Plugin<TPluginContext> & ExecutorPluginExtras {
28.   const EMPTY_ARRAY = Object.freeze([]);
29.   function executorToExecuteFn(executionArgs: ExecutionArgs) {
30.     return executor({
31.       document: executionArgs.document,
32.       rootValue: executionArgs.rootValue,
33.       context: executionArgs.contextValue,
34.       variables: executionArgs.variableValues,
35.       operationName: executionArgs.operationName,
36.     });
37.   }
38.   const pluginCtx: ExecutorPluginContext = {
39.     schema$: undefined,
40.     schema: undefined,
41.     schemaSetPromise$: undefined,
42.     skipIntrospection: false,
43.   };
44.   if (opts?.polling) {
45.     setInterval(() => {
46.       pluginCtx.schema$ = undefined;
47.       pluginCtx.schema = undefined;
48.     }, opts.polling);
49.   }
50.   function ensureSchema(ctx?: any) {
51.     if (pluginCtx.skipIntrospection) {
52.       return;
53.     }
54.     try {
55.       if (!pluginCtx.schema && !pluginCtx.schemaSetPromise$) {
56.         pluginCtx.schema$ ||= schemaFromExecutor(executor, ctx, opts);
57.         if (isPromise(pluginCtx.schema$)) {
58.           pluginCtx.schemaSetPromise$ = (
59.             pluginCtx.schema$.then(newSchema => {
60.               pluginCtx.schema = newSchema;
61.             }) as Promise<void>
62.           ).catch?.(err => {
63.             console.warn(
64.               `Introspection failed, skipping introspection due to the following errors;\n`,
65.               err,
66.             );
67.             pluginCtx.skipIntrospection = true;
68.           });
69.         } else {
70.           pluginCtx.schema = pluginCtx.schema$;
71.         }
72.       }
73.     } catch (err) {
74.       pluginCtx.skipIntrospection = true;
75.       console.warn(
76.         `Introspection failed, skipping introspection due to the following errors;\n`,
77.         err,
78.       );
79.     }
80.   }
81.   return {
82.     onEnveloped({ context, setSchema }) {
83.       ensureSchema(context);
84.       if (pluginCtx.schema) {
85.         setSchema(pluginCtx.schema);
86.       }
87.     },
88.     onContextBuilding() {
89.       ensureSchema();
90.       if (pluginCtx.schemaSetPromise$) {
91.         return pluginCtx.schemaSetPromise$ as Promise<void>;
92.       }
93.     },
94.     onExecute({ args, setExecuteFn }) {
95.       if (args.schema) {
96.         pluginCtx.schema = args.schema;
97.         pluginCtx.schema$ = pluginCtx.schema;
98.       }
99.       ensureSchema(args.contextValue);
100.       return mapMaybePromise(pluginCtx.schemaSetPromise$, () => {
101.         setExecuteFn(executorToExecuteFn);
102.       });
103.     },
