1. import { buildSchema, parse } from 'graphql';
2. import { envelop } from '@envelop/core';
3. import { useExecutor } from '@graphql-tools/executor-envelop';
4. import { Executor } from '@graphql-tools/utils';
5. 
6. describe('Envelop', () => {
7.   const schema = buildSchema(/* GraphQL */ `
8.     type Query {
9.       hello: String
10.     }
11.   `);
12.   const document = parse(/* GraphQL */ `
13.     query Greetings {
14.       hello
15.     }
16.   `);
17.   it('should pass the operation correctly with execute', async () => {
18.     const executor: Executor = jest.fn().mockImplementation(() => ({
19.       data: {
20.         hello: 'Hello World!',
21.       },
22.     }));
23.     const getEnveloped = envelop({
24.       plugins: [useExecutor(executor)],
25.     });
26.     const context = {};
27.     const { execute } = getEnveloped(context);
28.     const result = await execute({
29.       schema,
30.       document,
31.     });
32.     expect(result).toEqual({
33.       data: {
34.         hello: 'Hello World!',
35.       },
36.     });
37.     expect(executor).toHaveBeenCalledWith({
38.       document,
39.       context,
40.     });
41.   });
42.   it('should pass the operation correctly with subscribe', async () => {
43.     const executor: Executor = jest.fn().mockImplementation(async function* () {
44.       for (let i = 0; i < 3; i++) {
45.         yield {
46.           data: {
47.             count: i,
48.           },
49.         };
50.       }
51.     });
52.     const getEnveloped = envelop({
53.       plugins: [useExecutor(executor)],
54.     });
55.     const context = {};
56.     const { subscribe } = getEnveloped(context);
57.     const result = await subscribe({
58.       schema,
59.       document,
60.     });
61.     expect(result[Symbol.asyncIterator]).toBeDefined();
62.     const collectedResults: any[] = [];
63.     for await (const chunk of result as AsyncIterableIterator<any>) {
64.       collectedResults.push(chunk);
65.     }
66.     expect(collectedResults).toEqual([
67.       {
68.         data: {
69.           count: 0,
70.         },
71.       },
72.       {
73.         data: {
74.           count: 1,
75.         },
76.       },
77.       {
78.         data: {
79.           count: 2,
80.         },
81.       },
82.     ]);
83. 
84.     expect(executor).toBeCalledWith({
85.       document,
86.       context,
87.     });
88.   });
89.   it('should skip validation if schema is not provided', async () => {
90.     const executor: Executor = jest.fn().mockImplementation(() => {
91.       return {
92.         data: {
93.           hello: 'Hello World!',
94.         },
95.       };
96.     });
97.     const getEnveloped = envelop({
98.       plugins: [useExecutor(executor)],
99.     });
100.     const context = {};
101.     const { validate, execute } = getEnveloped(context);
102.     const validationResult = validate({}, document);
103.     expect(validationResult).toHaveLength(0);
104.     const result = await execute({
105.       schema: {},
106.       document,
107.     });
108.     expect(result).toEqual({
109.       data: {
110.         hello: 'Hello World!',
